types.decl:
typedef struct qttune_frame {
    uint64_t timestamp_us;    /* Microseconds since epoch or session start */
    uint32_t channel_id;      /* Logical channel (e.g., CAN bus ID) */
    uint8_t data[64];         /* Max CAN-FD payload size */
    uint8_t data_length;      /* Actual bytes used (0-64) */
    uint8_t is_extended;      /* Extended frame flag (29-bit address) */
    uint8_t rsvd[3];          /* Padding for alignment */
} qttune_frame_t;

typedef void (*qttune_frame_callback_t)(
    const qttune_frame_t* frame,
    void* user_data
);

typedef enum {
    QT_OK = 0,
    QT_ERR_NULL_ARGUMENT = 1,
    QT_ERR_NOT_IMPLEMENTED = 2,
    QT_ERR_NO_TRANSPORT = 3,
    QT_ERR_OUT_OF_MEMORY = 4,
    QT_ERR_SESSION_CLOSED = 5,
    QT_ERR_ALREADY_REGISTERED = 6,  /* Kept for backward compat if needed */
    QT_ERR_LOAD_FAILED = 7          /* New: DLL load/export resolution failed */
} qttune_status_t;

typedef struct qttune_transport_ops {
    qttune_status_t (*start)(qttune_session_t* session, void* impl);
    void (*detach)(qttune_session_t* session, void* impl);
} qttune_transport_ops_t;

typedef struct qttune_transport {
    const qttune_transport_ops_t* ops;
    void* impl;
} qttune_transport_t;

typedef struct qttune_j2534_device {
    uint32_t vendor_id;           /* Index in discovery order (0-based) */
    char vendor_name[QTTUNE_J2534_VENDOR_NAME_LEN];
    char dll_path[QTTUNE_J2534_DLL_PATH_LEN];
    uint32_t supported_protocols; /* 0 — reserved for PROTOCOLS bitmask parse */
    uint32_t reserved[8];         /* ABI-stable expansion room */
} qttune_j2534_device_t;

typedef struct QttuneSignalDef {
    uint16_t id;
    char name[32];
    QttuneSignalType type;
    uint8_t start_byte;
    uint8_t num_bytes;
    uint8_t bit_offset;
    uint8_t bit_length;
    float scale;
    float offset;
    char unit[16];
    uint8_t decimal_places;
    uint32_t flags;
    uint32_t reserved[3];
} QttuneSignalDef;

typedef struct QttuneSignalSet {
    uint32_t version;
    uint32_t count;
    const QttuneSignalDef* defs;
} QttuneSignalSet;
